"use client";

import { useState, useEffect } from "react";
import JobCard from "@/components/jobs/JobCard";
import PostJobForm from "@/components/jobs/PostJobForm";
import { Search, MapPin, Filter, Plus, Loader2 } from "lucide-react";
import { db } from "@/lib/firebase";
import { collection, query, orderBy, onSnapshot } from "firebase/firestore";
import { useAuth } from "@/context/AuthContext";
import { Job } from "@/types";

export default function JobsPage() {
    const { user } = useAuth();
    const [jobs, setJobs] = useState<Job[]>([]);
    const [filterCity, setFilterCity] = useState("New York, NY");
    const [showPostForm, setShowPostForm] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const q = query(collection(db, "jobs"), orderBy("postedAt", "desc"));

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const jobsData = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data(),
            })) as Job[];
            setJobs(jobsData);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    // Filter Logic
    const filteredJobs = jobs.filter(job =>
        job.location?.toLowerCase().includes(filterCity.toLowerCase()) || filterCity === ""
    );

    return (
        <div className="max-w-4xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 text-gradient bg-clip-text text-transparent">Local Opportunities</h1>
                    <p className="text-slate-500 mt-2">Find the best jobs in your area.</p>
                </div>

                <button
                    onClick={() => setShowPostForm(!showPostForm)}
                    className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-full font-semibold shadow-md transition"
                >
                    {showPostForm ? "Cancel" : <><Plus className="w-5 h-5" /> Post a Job</>}
                </button>
            </div>

            {showPostForm && (
                <div className="mb-8 animate-in fade-in slide-in-from-top-4 duration-300">
                    <PostJobForm onSuccess={() => setShowPostForm(false)} />
                </div>
            )}

            {/* Search & Filter Bar */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 mb-6 flex flex-col md:flex-row gap-4">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Search job titles or companies..."
                        className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-100 outline-none"
                    />
                </div>
                <div className="md:w-1/3 relative">
                    <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input
                        type="text"
                        value={filterCity}
                        onChange={(e) => setFilterCity(e.target.value)}
                        placeholder="City, State"
                        className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-100 outline-none"
                    />
                </div>
                <button className="px-4 py-2 bg-slate-100 text-slate-700 font-medium rounded-lg hover:bg-slate-200 flex items-center gap-2">
                    <Filter className="w-4 h-4" /> Filters
                </button>
            </div>

            <div className="space-y-4">
                <h2 className="font-semibold text-slate-700 mb-4">
                    Showing {filteredJobs.length} jobs in <span className="text-blue-600">{filterCity || "All Locations"}</span>
                </h2>

                {loading ? (
                    <div className="flex justify-center py-10"><Loader2 className="w-8 h-8 animate-spin text-blue-500" /></div>
                ) : filteredJobs.length > 0 ? (
                    filteredJobs.map((job) => (
                        <JobCard key={job.id} job={job} />
                    ))
                ) : (
                    <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                        <p className="text-slate-500">No jobs found in this location.</p>
                        <button
                            onClick={() => setFilterCity("")}
                            className="mt-2 text-blue-600 font-medium hover:underline"
                        >
                            View all locations
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import CourseCard from "@/components/learning/CourseCard";
import PostCourseForm from "@/components/learning/PostCourseForm";
import { Search, MapPin, Filter, Plus, Loader2 } from "lucide-react";
import { db } from "@/lib/firebase";
import { collection, query, orderBy, onSnapshot } from "firebase/firestore";
import { useAuth } from "@/context/AuthContext";
import { Course } from "@/types";

export default function LearningPage() {
    const { user } = useAuth();
    const [courses, setCourses] = useState<Course[]>([]);
    const [filterCity, setFilterCity] = useState("New York, NY");
    const [showPostForm, setShowPostForm] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const q = query(collection(db, "courses"), orderBy("createdAt", "desc"));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setCourses(data as Course[]);
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    const filteredCourses = courses.filter(course =>
        course.location?.toLowerCase().includes(filterCity.toLowerCase()) || filterCity === ""
    );

    return (
        <div className="max-w-4xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 text-gradient bg-clip-text text-transparent">Learning Center</h1>
                    <p className="text-slate-500 mt-2">Find courses, workshops, and local training.</p>
                </div>

                {user && (
                    <button
                        onClick={() => setShowPostForm(!showPostForm)}
                        className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-full font-semibold shadow-md transition"
                    >
                        {showPostForm ? "Cancel" : <><Plus className="w-5 h-5" /> Add Course</>}
                    </button>
                )}
            </div>

            {showPostForm && (
                <div className="mb-8 animate-in fade-in slide-in-from-top-4 duration-300">
                    <PostCourseForm onSuccess={() => setShowPostForm(false)} />
                </div>
            )}

            {/* Filter Bar */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 mb-6 flex flex-col md:flex-row gap-4">
                <div className="flex-1 relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input type="text" placeholder="Search topics..." className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 outline-none" />
                </div>
                <div className="md:w-1/3 relative">
                    <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input type="text" value={filterCity} onChange={(e) => setFilterCity(e.target.value)} placeholder="City" className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 outline-none" />
                </div>
            </div>

            <div className="space-y-4">
                {loading ? <div className="flex justify-center py-10"><Loader2 className="w-8 h-8 animate-spin text-blue-500" /></div> :
                    filteredCourses.length > 0 ? (
                        filteredCourses.map((course) => (
                            <CourseCard key={course.id} course={course} />
                        ))
                    ) : (
                        <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                            <p className="text-slate-500">No courses found here.</p>
                            <button onClick={() => setFilterCity("")} className="mt-2 text-blue-600 font-medium hover:underline">View all</button>
                        </div>
                    )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { db } from "@/lib/firebase";
import { collection, query, orderBy, onSnapshot } from "firebase/firestore";
import Sidebar from "@/components/layout/Sidebar";
import Navbar from "@/components/layout/Navbar";
import { Service } from "@/types";
import ServiceCard from "@/components/services/ServiceCard";
import PostServiceForm from "@/components/services/PostServiceForm";
import { Plus, X, Wrench } from "lucide-react";

export default function ServicesPage() {
    const { user } = useAuth();
    const [services, setServices] = useState<Service[]>([]);
    const [showPostForm, setShowPostForm] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const q = query(collection(db, "services"), orderBy("postedAt", "desc"));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const servicesData = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            })) as Service[];
            setServices(servicesData);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    return (
        <div className="min-h-screen bg-slate-50">
            <Navbar />
            <div className="flex">
                <Sidebar />
                <main className="flex-1 p-6 md:p-8 ml-0 md:ml-64">
                    <div className="max-w-4xl mx-auto space-y-6">
                        {/* Header */}
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-3xl font-bold text-slate-900 text-gradient bg-clip-text text-transparent">Local Services</h1>
                                <p className="text-slate-500 mt-1">Find skilled professionals or offer your services</p>
                            </div>

                            <button
                                onClick={() => setShowPostForm(!showPostForm)}
                                className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-full shadow-lg transition flex items-center justify-center gap-2"
                            >
                                {showPostForm ? <X className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
                                {showPostForm ? "Cancel" : "Offer a Service"}
                            </button>
                        </div>

                        {/* Post Service Form */}
                        {showPostForm && (
                            <div className="animate-in fade-in slide-in-from-top-4">
                                <PostServiceForm onSuccess={() => setShowPostForm(false)} />
                            </div>
                        )}

                        {/* Services List */}
                        {loading ? (
                            <div className="flex justify-center py-12">
                                <Wrench className="w-8 h-8 text-slate-300 animate-spin" />
                            </div>
                        ) : services.length === 0 ? (
                            <div className="text-center py-12 bg-white rounded-xl border border-slate-100 shadow-sm">
                                <Wrench className="w-12 h-12 text-slate-300 mx-auto mb-3" />
                                <h3 className="text-lg font-semibold text-slate-700">No services yet</h3>
                                <p className="text-slate-500">Be the first to offer a service in your area!</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {services.map(service => (
                                    <ServiceCard key={service.id} service={service} />
                                ))}
                            </div>
                        )}
                    </div>
                </main>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { Users, FileText, Trash2, Shield, ShieldCheck } from "lucide-react";

import { UserProfile } from "@/types";

export default function AdminDashboard() {
    const [users, setUsers] = useState<UserProfile[]>([]);
    const [postsCount, setPostsCount] = useState(0);
    const [loading, setLoading] = useState(true);

    const fetchData = async () => {
        try {
            // Fetch Users
            const usersSnap = await getDocs(collection(db, "users"));
            setUsers(usersSnap.docs.map(d => d.data() as UserProfile));

            // Fetch Posts Count (not efficient for large DBs, but fine for now)
            const postsSnap = await getDocs(collection(db, "posts"));
            setPostsCount(postsSnap.size);

            setLoading(false);
        } catch (error) {
            console.error("Admin fetch error:", error);
        }
    };

    useEffect(() => {
        fetchData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const makeAdmin = async (userId: string) => {
        if (confirm("Promote this user to Admin?")) {
            await updateDoc(doc(db, "users", userId), { role: "admin" });
            fetchData(); // Refresh
        }
    };

    const deleteUser = async (userId: string) => {
        if (confirm("Are you sure you want to delete this user? This cannot be undone.")) {
            await deleteDoc(doc(db, "users", userId));
            // Ideally delete their posts too
            fetchData();
        }
    };

    if (loading) return <div>Loading dashboard...</div>;

    return (
        <div className="space-y-8">
            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center gap-4">
                    <div className="p-3 bg-blue-100 text-blue-600 rounded-lg"><Users className="w-6 h-6" /></div>
                    <div>
                        <p className="text-slate-500 text-sm font-medium">Total Users</p>
                        <h3 className="text-2xl font-bold text-slate-900">{users.length}</h3>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center gap-4">
                    <div className="p-3 bg-green-100 text-green-600 rounded-lg"><FileText className="w-6 h-6" /></div>
                    <div>
                        <p className="text-slate-500 text-sm font-medium">Total Posts</p>
                        <h3 className="text-2xl font-bold text-slate-900">{postsCount}</h3>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center gap-4">
                    <div className="p-3 bg-purple-100 text-purple-600 rounded-lg"><Shield className="w-6 h-6" /></div>
                    <div>
                        <p className="text-slate-500 text-sm font-medium">Admins</p>
                        <h3 className="text-2xl font-bold text-slate-900">{users.filter(u => u.role === "admin").length}</h3>
                    </div>
                </div>
            </div>

            {/* User Management Table */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100">
                    <h2 className="text-lg font-bold text-slate-800">User Management</h2>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="bg-slate-50 text-slate-700 uppercase font-medium">
                            <tr>
                                <th className="px-6 py-3">User</th>
                                <th className="px-6 py-3">Role</th>
                                <th className="px-6 py-3">City</th>
                                <th className="px-6 py-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map(user => (
                                <tr key={user.uid} className="border-b border-slate-50 hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium text-slate-900">
                                        <div>{user.displayName}</div>
                                        <div className="text-slate-400 text-xs">{user.email}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${user.role === 'admin' ? 'bg-purple-100 text-purple-700' : 'bg-slate-100 text-slate-600'
                                            }`}>
                                            {user.role || 'user'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">{user.city}</td>
                                    <td className="px-6 py-4 text-right flex justify-end gap-2">
                                        {user.role !== 'admin' && (
                                            <button onClick={() => makeAdmin(user.uid)} className="text-blue-600 hover:text-blue-800 p-1" title="Promote to Admin">
                                                <ShieldCheck className="w-4 h-4" />
                                            </button>
                                        )}
                                        <button onClick={() => deleteUser(user.uid)} className="text-red-500 hover:text-red-700 p-1" title="Delete User">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useAuth } from "@/context/AuthContext";
import { db } from "@/lib/firebase";
import { collection, query, where, orderBy, onSnapshot } from "firebase/firestore";
import { Conversation } from "@/types";
import { Search, Loader2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface ChatListProps {
    onSelect: (conv: Conversation) => void;
    selectedId?: string;
}

export default function ChatList({ onSelect, selectedId }: ChatListProps) {
    const { user } = useAuth();
    const [conversations, setConversations] = useState<Conversation[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");

    useEffect(() => {
        if (!user) return;

        // Query conversations where current user is a participant
        const q = query(
            collection(db, "conversations"),
            where("participants", "array-contains", user.uid),
            orderBy("lastMessageAt", "desc")
        );

        const unsubscribe = onSnapshot(q, async (snapshot) => {
            const convsPromises = snapshot.docs.map(async (doc) => {
                const data = doc.data() as Omit<Conversation, "id">;
                const otherUid = data.participants.find(p => p !== user.uid);

                // Fetch other user profile (simple cache-less invite for MVP)
                // In production, use a user cache or separate profiles collection
                let otherUser = { displayName: "Unknown", photoURL: "", uid: otherUid || "" };

                if (otherUid) {
                    // We can't really async fetch inside map for real-time efficiency without cache
                    // For now, we'll just store UID or fetch if critical. 
                    // Better approach: Store essential user info IN the conversation document 
                    // to avoid N+1 queries. Let's assume we do that or just show UID for now 
                    // until we add user-sync to conversations.
                    // Or, we'll try to fetch it here - it's okay for < 50 chats.
                    // (Omitting fetch for brevity/performance in this block, will rely on what's available
                    // or implement a quick lookup if needed. For this demo, let's assume we have a helper 
                    // or just use a placeholder).
                    // Actually, let's do a quick fetch or listen.
                }

                return {
                    id: doc.id,
                    ...data,
                    otherUser // Placeholder, will populate properly in a real app or with stored data
                };
            });

            const convs = await Promise.all(convsPromises);
            setConversations(convs);
            setLoading(false);
        });

        return () => unsubscribe();
    }, [user]);

    const filteredConvs = conversations.filter(c =>
        c.lastMessage.toLowerCase().includes(searchTerm.toLowerCase())
        // || c.otherUser?.displayName...
    );

    if (loading) return <div className="p-4 flex justify-center"><Loader2 className="animate-spin text-blue-500" /></div>;

    return (
        <div className="flex-1 flex flex-col overflow-hidden">
            {/* Search */}
            <div className="p-4 pt-2">
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Search chats..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-100 transition"
                    />
                </div>
            </div>

            {/* List */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
                {filteredConvs.length === 0 ? (
                    <div className="text-center text-slate-400 text-sm mt-10">No messages found.</div>
                ) : (
                    filteredConvs.map(conv => (
                        <div
                            key={conv.id}
                            onClick={() => onSelect(conv)}
                            className={`
                                p-3 rounded-xl cursor-pointer transition-all duration-200 flex items-center gap-3
                                ${selectedId === conv.id
                                    ? 'bg-blue-50/80 border-blue-100 shadow-sm'
                                    : 'hover:bg-slate-50 border border-transparent'}
                            `}
                        >
                            {/* Avatar */}
                            <div className="relative">
                                <div className="w-12 h-12 rounded-full bg-slate-200 flex flex-shrink-0 overflow-hidden">
                                    <img
                                        src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${conv.participants.find(p => p !== user?.uid)}`}
                                        alt="User"
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                                {conv.unreadCount?.[user?.uid || ''] > 0 && (
                                    <span className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-blue-500 border-2 border-white"></span>
                                )}
                            </div>

                            {/* Info */}
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between items-baseline mb-0.5">
                                    <h3 className={`text-sm font-semibold truncate ${selectedId === conv.id ? 'text-blue-700' : 'text-slate-800'}`}>
                                        User {conv.participants.find(p => p !== user?.uid)?.slice(0, 4)}...
                                    </h3>
                                    <span className="text-[10px] text-slate-400 font-medium">
                                        {conv.lastMessageAt?.toDate ? formatDistanceToNow(conv.lastMessageAt.toDate(), { addSuffix: false }) : ''}
                                    </span>
                                </div>
                                <p className={`text-xs truncate ${conv.unreadCount?.[user?.uid || ''] > 0 ? 'font-bold text-slate-800' : 'text-slate-500'}`}>
                                    {conv.lastMessage || "Started a conversation"}
                                </p>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useAuth } from "@/context/AuthContext";
import { db } from "@/lib/firebase";
import { collection, query, orderBy, onSnapshot, addDoc, serverTimestamp, updateDoc, doc, setDoc } from "firebase/firestore";
import { Conversation, Message } from "@/types";
import { Send, ArrowLeft, MoreVertical, Phone, Video } from "lucide-react";

interface ChatWindowProps {
    conversation: Conversation;
    onBack?: () => void;
}

export default function ChatWindow({ conversation, onBack }: ChatWindowProps) {
    const { user } = useAuth();
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState("");
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const otherUid = conversation.participants.find(p => p !== user?.uid);

    // Auto-scroll
    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        if (!conversation.id) return;

        const q = query(
            collection(db, "conversations", conversation.id, "messages"),
            orderBy("createdAt", "asc")
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const msgs = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            })) as Message[];
            setMessages(msgs);
            // Mark as read could go here
            setTimeout(scrollToBottom, 100);
        });

        return () => unsubscribe();
    }, [conversation.id]);

    const handleSend = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !user) return;

        const text = newMessage.trim();
        setNewMessage("");

        const convoRef = doc(db, "conversations", conversation.id);
        const messagesRef = collection(convoRef, "messages");

        await addDoc(messagesRef, {
            text,
            senderId: user.uid,
            createdAt: serverTimestamp(),
            read: false
        });

        // Update conversation summary
        await updateDoc(convoRef, {
            lastMessage: text,
            lastMessageAt: serverTimestamp(),
            // unreadCount logic would ideally be atomic increment for the OTHER user
            [`unreadCount.${otherUid}`]: (conversation.unreadCount?.[otherUid || ''] || 0) + 1
        });
    };

    return (
        <>
            {/* Header */}
