                                <h3 className="font-semibold text-slate-900">{post.authorName}</h3>
                                <p className="text-xs text-slate-500">
                                    {post.createdAt?.toDate ? formatDistanceToNow(post.createdAt.toDate(), { addSuffix: true }) : "Just now"}
