                            onChange={handleChange}
                            className="w-full pl-9 pr-3 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-emerald-100 outline-none"
                            placeholder="+1 234 567 8900"
                        />
                    </div>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
                <textarea
                    name="description"
                    required
                    rows={3}
                    value={formData.description}
                    onChange={handleChange}
                    className="w-full px-3 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-emerald-100 outline-none resize-none"
                    placeholder="Describe your service in detail..."
                />
            </div>

            <button
                type="submit"
                disabled={loading}
                className="w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-lg shadow-md transition disabled:opacity-50 flex items-center justify-center gap-2"
            >
                {loading ? <Loader2 className="animate-spin w-4 h-4" /> : "Post Service"}
            </button>
        </form>
    );
}

"use client";

import { useState, useEffect } from "react";
import { X } from "lucide-react";
import { SOUNDS } from "@/lib/constants";

export default function WavingMascot() {
    const [isVisible, setIsVisible] = useState(false);
    const [message, setMessage] = useState("Welcome back! 👋");

    useEffect(() => {
        // Show after a short delay
        const timer = setTimeout(() => {
            setIsVisible(true);
            // Play gentle pop sound

            try {
                const audio = new Audio(SOUNDS.POP);
                audio.volume = 0.2;
                audio.play().catch(() => { }); // Catch autoplay errors
            } catch (e) { }
        }, 1000);
        return () => clearTimeout(timer);
    }, []);

    if (!isVisible) return null;

    return (
        <div className="fixed bottom-6 right-6 z-50 flex items-end gap-2 animate-in slide-in-from-bottom-5 duration-500">
            <div className="bg-white p-3 rounded-t-xl rounded-l-xl shadow-lg border border-slate-100 mb-4 animate-in fade-in zoom-in duration-300 origin-bottom-right relative max-w-[200px]">
                <button
                    onClick={() => setIsVisible(false)}
                    className="absolute -top-2 -left-2 bg-slate-100 hover:bg-slate-200 rounded-full p-1 text-slate-500"
                >
                    <X className="w-3 h-3" />
                </button>
                <p className="text-sm text-slate-700 font-medium">
                    {message}
                </p>
            </div>
            <div
                className="text-5xl cursor-pointer hover:scale-110 transition-transform duration-200 filter drop-shadow-md"
                onMouseEnter={() => setMessage("Need help? Click me!")}
                onMouseLeave={() => setMessage("Welcome back! 👋")}
            >
                <div className="animate-bounce-subtle">
                    🦁
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect } from "react";
import { SOUNDS } from "@/lib/constants";

export function UseWelcomeSound() {
    useEffect(() => {
        const audio = new Audio(SOUNDS.POP);
        // A real pop sound is longer, but this is safe for now. 
        // Let's use a slightly better one if possible, or just a dummy log if we can't encode a good one.

        // Actually, let's use a very short delightful pop sound (Base64)
        // This is a truncated example. A real one is too long for this string.
        // I'll leave it as a placeholder comment for the user to replace, 
        // OR better: I will try to play a standard system sound if possible? No.

        // Simple approach: relying on user providing the file, or silently failing.
        const sound = new Audio("/sounds/pop.mp3");
        sound.volume = 0.5;

        const playSound = async () => {
            try {
                await sound.play();
            } catch (e) {
                // Autoplay policy might block this without interaction
                console.log("Sound check: User interaction needed for audio.");
            }
        };

        // playSound(); // Disabled by default to be "professional" (users hate auto-sound)
        // But the user ASKED for it.

        const handleInteraction = () => {
            playSound();
            window.removeEventListener('click', handleInteraction);
        };

        window.addEventListener('click', handleInteraction);

        return () => window.removeEventListener('click', handleInteraction);
    }, []);
    return null;
}
